// Reads the latest hubstaff_uploads rows, compares them against a persisted
// cursor (the newest uploaded_at we've already alerted on), and emits ONLY rows
// that are newer. On the very first run it silently seeds the cursor so you do
// NOT get one email per historical upload.

const store = $getWorkflowStaticData('global');

// --- 1. Collect rows defensively (HTTP node array handling varies by version) ---
const rows = [];
for (const it of $input.all()) {
  const j = it.json;
  if (Array.isArray(j)) rows.push(...j);
  else if (j && Array.isArray(j.body)) rows.push(...j.body);
  else if (j && Array.isArray(j.data)) rows.push(...j.data);
  else if (j && j.id) rows.push(j);
}

if (rows.length === 0) return [];

// --- 2. Sort newest-first by uploaded_at ---
rows.sort((a, b) => new Date(b.uploaded_at) - new Date(a.uploaded_at));
const newestTs = rows[0].uploaded_at;

const cursor = store.lastSeenUploadedAt || null;

// --- 3. First activation: seed the cursor, alert on nothing ---
if (!cursor) {
  store.lastSeenUploadedAt = newestTs;
  return [];
}

// --- 4. Keep rows strictly newer than the cursor ---
const fresh = rows.filter(r => new Date(r.uploaded_at) > new Date(cursor));

// --- 5. Advance the cursor ---
store.lastSeenUploadedAt = newestTs;

// --- 6. Attach a friendly Manila timestamp for the email ---
return fresh.map(r => {
  let when = r.uploaded_at;
  try {
    when = DateTime.fromISO(r.uploaded_at, { zone: 'utc' })
      .setZone('Asia/Manila')
      .toFormat("LLL d, yyyy '-' h:mm a '(PHT)'");
  } catch (e) {}
  return { json: Object.assign({}, r, { uploaded_at_display: when }) };
});
